export class ExerciseNormalizer{constructor(){this.exerciseCache=new Map,this.existingExercises=[]}loadExistingExercises(){const exercises=new Set;try{const logs=JSON.parse(localStorage.getItem("ironflow_logs")||"[]");logs.forEach(log=>{(log.exercises||[]).forEach(ex=>{ex.name&&exercises.add(ex.name.trim())})})}catch(e){console.warn("[ExerciseNormalizer] Failed to parse ironflow_logs:",e.message)}try{const workouts=JSON.parse(localStorage.getItem("ironflow_workouts")||"[]");workouts.forEach(workout=>{(workout.exercises||[]).forEach(ex=>{ex.name&&exercises.add(ex.name.trim())})})}catch(e){console.warn("[ExerciseNormalizer] Failed to parse ironflow_workouts:",e.message)}try{const prs=JSON.parse(localStorage.getItem("ironflow_personal_records")||"{}");Object.values(prs).forEach(pr=>{pr.displayName&&exercises.add(pr.displayName)})}catch(e){console.warn("[ExerciseNormalizer] Failed to parse ironflow_personal_records:",e.message)}return this.existingExercises=Array.from(exercises).sort(),this.existingExercises}getExerciseListForPrompt(){return this.loadExistingExercises(),0===this.existingExercises.length?"Nessun esercizio esistente nel database.":this.existingExercises.join("\n")}normalizeLocally(exerciseName){if(!exerciseName)return exerciseName;const normalized=this._normalizeString(exerciseName);for(const existing of this.existingExercises)if(this._normalizeString(existing)===normalized)return existing;for(const existing of this.existingExercises)if(this._calculateSimilarity(normalized,this._normalizeString(existing))>.85)return existing;return exerciseName}async normalizeWithAI(exerciseNames,apiKey){return console.warn("normalizeWithAI is deprecated. Use normalizeWithCloudFunction instead."),exerciseNames&&0!==exerciseNames.length?(this.loadExistingExercises(),0===this.existingExercises.length?exerciseNames:exerciseNames.map(name=>this.normalizeLocally(name))):exerciseNames}async normalizeWithCloudFunction(exerciseNames,generateContentCallable){if(!generateContentCallable||!exerciseNames||0===exerciseNames.length)return exerciseNames;if(this.loadExistingExercises(),0===this.existingExercises.length)return exerciseNames;const uncached=exerciseNames.filter(name=>!this.exerciseCache.has(name));if(0===uncached.length)return exerciseNames.map(name=>this.exerciseCache.get(name)||name);try{const prompt=`Sei un assistente per la normalizzazione dei nomi degli esercizi di palestra.\n\nESERCIZI GIÀ ESISTENTI NEL DATABASE:\n${this.existingExercises.join("\n")}\n\nESERCIZI DA NORMALIZZARE:\n${uncached.join("\n")}\n\nREGOLE IMPORTANTI:\n1. Se un esercizio da normalizzare è IDENTICO o SEMANTICAMENTE EQUIVALENTE a uno esistente, ritorna ESATTAMENTE il nome esistente (stesso casing, stessa stringa)\n2. Considera equivalenti variazioni come: singolare/plurale, con/senza articoli, abbreviazioni comuni\n3. Se l'esercizio è NUOVO e non ha equivalenti, ritornalo esattamente come fornito\n4. NON inventare nuovi nomi, NON modificare la formattazione se non necessario\n\nFORMATO RISPOSTA (JSON array, mantenendo l'ordine):\n["nome1", "nome2", ...]\n\nRispondi SOLO con il JSON array, nient'altro.`,result=await generateContentCallable({prompt,config:{temperature:.1,maxOutputTokens:1024},modelName:"gemini-3-flash-preview"}),text=result.data.text.trim(),jsonMatch=text.match(/\[[\s\S]*\]/);if(jsonMatch){const normalized=JSON.parse(jsonMatch[0]);return uncached.forEach((name,i)=>{normalized[i]&&this.exerciseCache.set(name,normalized[i])}),exerciseNames.map(name=>this.exerciseCache.get(name)||name)}}catch(error){console.warn("Exercise normalization Cloud Function failed:",error)}return exerciseNames.map(name=>this.normalizeLocally(name))}getAINormalizationPrompt(){return this.loadExistingExercises(),0===this.existingExercises.length?"":`\nIMPORTANTE - NORMALIZZAZIONE NOMI ESERCIZI:\nL'utente ha già registrato questi esercizi nel database:\n${this.existingExercises.slice(0,50).join(", ")}${this.existingExercises.length>50?`... e altri ${this.existingExercises.length-50} esercizi`:""}\n\nREGOLA CRITICA: Se devi suggerire un esercizio che è CONCETTUALMENTE IDENTICO a uno già esistente nella lista sopra, DEVI usare ESATTAMENTE lo stesso nome (stesso casing, stessa stringa) già presente nel database.\nSolo se l'esercizio è completamente NUOVO e non sovrapponibile a quelli esistenti, puoi creare un nome nuovo.\nQuesto garantisce coerenza nei dati e nelle statistiche dell'utente.\n\n`}_normalizeString(str){return(str||"").toLowerCase().trim().replace(/\s+/g," ").replace(/[()[\]{}]/g,"").normalize("NFD").replace(/[\u0300-\u036f]/g,"")}_calculateSimilarity(str1,str2){if(str1===str2)return 1;if(!str1||!str2)return 0;const getBigrams=str=>{const bigrams=new Set;for(let i=0;i<str.length-1;i++)bigrams.add(str.slice(i,i+2));return bigrams},bigrams1=getBigrams(str1),bigrams2=getBigrams(str2);let intersection=0;return bigrams1.forEach(b=>{bigrams2.has(b)&&intersection++}),2*intersection/(bigrams1.size+bigrams2.size)}}export const exerciseNormalizer=new ExerciseNormalizer;